local function H(s)
    local t={}
    for i=1,#s,2 do t[#t+1]=string.char(tonumber(string.sub(s,i,i+1),16)) end
    return table.concat(t)
end
local function X(d,k)
    local o,kl={},#k
    for i=1,#d do
        o[i]=string.char(bit32.bxor(string.byte(d,i), string.byte(k, ((i-1)%kl)+1)))
    end
    return table.concat(o)
end
local B='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function D64(data)
    data=string.gsub(data,'[^'..B..'=]','')
    return (string.gsub(string.gsub(data,'.',function(x)
        if x=='=' then return '' end
        local r,f='',(string.find(B,x,1,true)-1)
        for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
        return r
    end),'%d%d%d?%d?%d?%d?%d?%d?',function(x)
        if #x~=8 then return '' end
        local c=0
        for i=1,8 do if string.sub(x,i,i)=='1' then c=c+2^(8-i) end end
        return string.char(c)
    end))
end
local function J(t)
    return table.concat(t,'')
end
local function R(i)
    local raw=D64(J(P[i]))
    return X(raw, H(K[i]))
end
local buf={}
for i=1,#P do
    buf[i]=R(i)
end
local src=table.concat(buf)
local fn,err=loadstring(src)
if not fn then
    fn,err=load(src)
end
if not fn then
    error('[KFC lattice] load failed: '..tostring(err))
end
fn()
